        ohp = float(opp.get('hp', 0))
        onw = float(opp.get('no_water_days', 0))
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if ob >= 140 and ohp >= 6:
            rich_threats += 1
        if onw >= 1 or ohp <= 4:
